import {readFileSync,writeFileSync} from "node:fs";
import {gunzipSync} from "node:zlib";
import assert from "node:assert/strict";
import {reviewIdleResearchBatch,initialIdleResearch,JUP_REL_MIN,JUP_VOLUME_MIN,type IdleTapeRow} from "../lib/stable4-idle-research-policy";
import {buildFetBrk48Signal,normalizeFetH1} from "../lib/fet-brk48-signal";
const B=String.raw`C:\tmp\disdex-bt-20251001-20261001`,R=String.raw`C:\tmp\disdex-d126-crossrunner-research-20261126`,H=3600000;
const begin=Date.parse("2025-10-01T00:00:00Z"),end=Date.parse("2026-10-01T00:00:00Z");
const jsonl=(p:string)=>readFileSync(p,"utf8").trim().split(/\r?\n/).map(x=>JSON.parse(x));
const raw:IdleTapeRow[]=jsonl(B+"/DIRECTION_RESEARCH_20261109/IDLE_CURRENT_PRODUCTION_REPLAY_20261110/idle-production-candidates-with-m5-exits.jsonl").filter(x=>x.entryTs>=begin&&x.entryTs<end);
const windows=raw.filter(x=>x.route==="IDLE_TAO_BREAKDOWN_SHORT_RELWEAK2").map(x=>[x.entryTs,x.entryTs+12*H]);
const reference=raw.filter(x=>x.route!=="IDLE_RENDER_RELATIVE_SHORT"&&!windows.some(([a,b])=>a<=x.entryTs&&x.entryTs<b)&&(x.route!=="IDLE_JUP_RELATIVE_SHORT"||(x.features.rel24>=JUP_REL_MIN&&x.features.volumeRatio>=JUP_VOLUME_MIN)));
const key=(x:IdleTapeRow)=>[x.entryTs,x.symbol,x.route].join("|");
const groups=new Map<number,IdleTapeRow[]>();for(const x of raw){const a=groups.get(x.entryTs)??[];a.push(x);groups.set(x.entryTs,a);}
let state=initialIdleResearch();const retained:IdleTapeRow[]=[];const counts:Record<string,number>={};
for(const [t,rows] of [...groups].sort((a,b)=>a[0]-b[0])){
 const x=reviewIdleResearchBatch(state,t,rows);state=JSON.parse(JSON.stringify(x.state));
 for(const d of x.decisions){assert.equal(d.orderAuthority,false);counts[d.reason]=(counts[d.reason]??0)+1;if(d.retained)retained.push(d.row);}
}
const a=retained.map(key).sort(),b=reference.map(key).sort();
assert.deepEqual(a,b);assert.equal(raw.length,849);assert.equal(retained.length,197);
const fet=jsonl(B+"/native-new-signal-20251001-20261001/native-FET-raw-intentions.jsonl").filter(x=>x.entryTs>=begin&&x.entryTs<end);
const bars=JSON.parse("["+gunzipSync(readFileSync(B+"/aster-public-v3-h1/FETUSDT-1h-20250924-20261001.jsonl.gz")).toString("utf8").trim().split(/\r?\n/).join(",")+"]");
const normalized=normalizeFetH1(bars,end);
const actual:number[]=[];
for(let t=begin;t<end;t+=H){
 const x=buildFetBrk48Signal(normalized.filter(r=>r.openTs>=t-80*H&&r.openTs<t),t);
 if(x)actual.push(x.entryTs);
}
const expected=fet.map(x=>x.entryTs).sort((a,b)=>a-b);
const missing=expected.filter(t=>!actual.includes(t)),extra=actual.filter(t=>!expected.includes(t));
const out={idle:{input:raw.length,retained:retained.length,counts,matched:a.length},fet:{expected:expected.length,actual:actual.length,missing,extra}};
writeFileSync(R+"/STABLE4_IDLE_FET_RESEARCH_PARITY_20261127.json",JSON.stringify(out,null,2));console.log(JSON.stringify(out));
if(missing.length||extra.length)process.exitCode=1;
